function read<T>(key:string,fallback:T):T{try{const raw=localStorage.getItem(key);if(!raw)return fallback;const value=JSON.parse(raw);if(key==='daylo_tasks'&&Array.isArray(value)&&value.some(item=>item?.title==='Review Q3 product roadmap'))return fallback;if(key==='daylo_notes'&&Array.isArray(value)&&value.some(item=>item?.id==='n1'))return fallback;if(key==='daylo_goals'&&Array.isArray(value)&&value.some(item=>item?.id==='g1'||item?.id==='g2'))return fallback;if(key==='daylo_habits'&&Array.isArray(value)&&value.length===2&&value.includes('Move your body')&&value.includes('Read a little'))return fallback;return value}catch{return fallback}}
function useSaved<T>(key:string,initial:T){const [v,setV]=useState(initial);const [ready,setReady]=useState(false);useEffect(()=>{setV(read(key,initial));setReady(true)},[key]);useEffect(()=>{if(ready)localStorage.setItem(key,JSON.stringify(v))},[key,v,ready]);return [v,setV] as const}
function dateKey(date:Date){return `${date.getFullYear()}-${String(date.getMonth()+1).padStart(2,'0')}-${String(date.getDate()).padStart(2,'0')}`}
function getWeekDays(anchor=new Date()){const start=new Date(anchor);start.setHours(0,0,0,0);start.setDate(start.getDate()-((start.getDay()+6)%7));return Array.from({length:7},(_,index)=>{const date=new Date(start);date.setDate(start.getDate()+index);return {key:dateKey(date),label:new Intl.DateTimeFormat('en',{weekday:'short'}).format(date).slice(0,1),date}})}
function messageInline(text:string){return text.split(/(\*\*.+?\*\*|\*.+?\*|`.+?`)/g).map((part,index)=>part.startsWith('**')&&part.endsWith('**')?<strong key={index}>{part.slice(2,-2)}</strong>:part.startsWith('*')&&part.endsWith('*')?<em key={index}>{part.slice(1,-1)}</em>:part.startsWith('`')&&part.endsWith('`')?<code key={index}>{part.slice(1,-1)}</code>:<span key={index}>{part}</span>)}
function MessageContent({content}:{content:string}){return <div className="message-content">{content.split('\n').map((line,index)=>{const trimmed=line.trim();if(!trimmed)return <div className="message-line message-break" key={index} aria-hidden="true"/>;if(trimmed.startsWith('>'))return <blockquote className="message-quote" key={index}>{messageInline(trimmed.replace(/^>\s?/,''))}</blockquote>;const bullet=trimmed.match(/^(?:[-*]|\d+\.)\s+(.*)$/);return <div className={`message-line${bullet?' message-list-item':''}`} key={index}>{messageInline(bullet?bullet[1]:line)}</div>})}</div>}

